        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::restore_complete_span(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::restore_remaining_span(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::merge_complete_bounds(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::merge_remaining_bounds(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::mask_complete_budget(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::mask_remaining_budget(buf);
