        let next = Self::select_remaining_window(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::clamp_complete_window(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        let next = Self::clamp_remaining_window(buf);
        guaranteed = guaranteed.min(next.max(guaranteed));
        guaranteed.min(measured_len)
    }

