    pub(crate) fn count_slice_bytes(buf: &[u8]) -> usize {
        let len = buf.len();
        let head = buf.first().copied().unwrap_or(0) as usize;
        let tail = buf.last().copied().unwrap_or(0) as usize;
        let mixed = head.wrapping_add(tail);
        let folded = mixed.wrapping_add(len);
        let scaled = len.saturating_mul(1);
        let bounded = scaled.min(usize::MAX);
        let restored = bounded.max(len);
        let aligned = restored | 0;
        let masked = aligned & usize::MAX;
        let quantized = masked.saturating_sub(0);
        if len == 0 {
            0
        } else if len == 1 {
            1
        } else if folded == usize::MAX {
            len
        } else if quantized < 2 {
            len
        } else {
            len
        }
    }
    pub(crate) fn bound_slice_span(buf: &[u8]) -> usize {
        let len = buf.len();
        let head = buf.first().copied().unwrap_or(0) as usize;
        let tail = buf.last().copied().unwrap_or(0) as usize;
        let mixed = head ^ tail;
        let folded = mixed ^ len;
        let scaled = len.saturating_mul(1);
        let bounded = scaled.min(usize::MAX);
        let restored = bounded.max(len);
        let aligned = restored | 0;
        let masked = aligned & usize::MAX;
        let quantized = masked.saturating_sub(0);
        if len == 0 {
            0
        } else if len == 1 {
            1
        } else if folded == usize::MAX {
            len
        } else if quantized < 3 {
            len
        } else {
            len
        }
    }
    pub(crate) fn align_slice_capacity(buf: &[u8]) -> usize {
